INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-a4-field', 'Сколько листов A4 размером 210 × 297 мм потребуется по площади, чтобы покрыть футбольное поле 105 × 68 м? Считай без нахлёста и отходов на обрезку.', 'Сколько листов A4 покроют футбольное поле?', 'листов', 114478, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-05', '{"steps":[{"label":"Площадь поля по размерам из условия","value":7140,"unit":"м²","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод единиц; размеры заданы условием"},{"label":"Площадь листа по размерам из условия","value":0.06237,"unit":"м²","sourceUrl":"https://www.iso.org/standard/36631.html","sourceTitle":"ISO 216 — форматы бумаги; размеры заданы условием"}],"summary":"7140 ÷ (0,210 × 0,297) ≈ 114 478 листов. Сравниваем площади, не решаем задачу раскладки."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-bricks-container', 'Сколько кирпичей 25 × 12 × 6 см поместится по суммарному объёму в грузовом контейнере с внутренними размерами 6 × 2,4 × 2,4 м? Игнорируй пустоты и ограничение по массе.', 'Сколько кирпичей по объёму войдёт в контейнер?', 'кирпичей', 19200, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-06', '{"steps":[{"label":"Объём контейнера по условию","value":34.56,"unit":"м³","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод единиц; размеры заданы условием"},{"label":"Объём кирпича по условию","value":0.0018,"unit":"м³","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Расчёт по размерам из условия"}],"summary":"34,56 ÷ (0,25 × 0,12 × 0,06) = 19 200 кирпичей по объёму."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-tennis-classroom', 'Сколько теннисных мячей диаметром 6,7 см войдёт в пустой класс 8 × 6 × 3 м, если сами мячи занимают 64% объёма, а остальное — промежутки между ними?', 'Сколько теннисных мячей войдёт в школьный класс?', 'мячей', 585220, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-07', '{"steps":[{"label":"Объём класса по условию","value":144,"unit":"м³","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Расчёт по размерам из условия"},{"label":"Доля объёма, занятая мячами, задана условием","value":0.64,"unit":"","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Допущение задачи"},{"label":"Диаметр мяча задан условием","value":0.067,"unit":"м","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод сантиметров в метры"}],"summary":"144 × 0,64 ÷ [4π/3 × (0,067/2)³] ≈ 585 тыс. мячей. Краевые эффекты игнорируем."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-million-seconds', 'Сколько суток длится миллион секунд? Можно ответить дробным числом.', 'Миллион секунд — это сколько суток?', 'суток', 11.5740740741, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-08', '{"steps":[{"label":"Продолжительность суток","value":86400,"unit":"с","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — day = 86 400 s"}],"summary":"1 000 000 ÷ 86 400 ≈ 11,57 суток. Это 11 суток 13 часов 46 минут 40 секунд."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-coffee-pool', 'Сколько чашек кофе по 250 мл потребуется, чтобы заполнить бассейн 50 × 25 м с одинаковой глубиной 2 м?', 'Сколько чашек кофе заполнит бассейн?', 'чашек', 10000000, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-09', '{"steps":[{"label":"Объём бассейна по условию","value":2500000,"unit":"л","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — 1 м³ = 1000 л; размеры заданы условием"},{"label":"Объём чашки по условию","value":0.25,"unit":"л","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод миллилитров в литры"}],"summary":"50 × 25 × 2 × 1000 ÷ 0,25 = 10 млн чашек."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-phone-km', 'Сколько смартфонов длиной 15 см нужно выложить торцами вплотную друг к другу, чтобы получился ряд длиной не меньше километра?', 'Сколько смартфонов в ряду длиной километр?', 'смартфонов', 6667, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-10', '{"steps":[{"label":"Длина ряда","value":100000,"unit":"см","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод километров в сантиметры"},{"label":"Длина смартфона задана условием","value":15,"unit":"см","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Допущение задачи"}],"summary":"100 000 ÷ 15 = 6666⅔. Округляем вверх до 6667 целых смартфонов."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-rice-person', 'Сколько сухих зёрен риса весят как человек массой 70 кг, если для этой прикидки принять массу одного зерна за 25 мг?', 'Сколько зёрен риса весят как человек?', 'зёрен', 2800000, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-11', '{"steps":[{"label":"Масса человека задана условием","value":70000000,"unit":"мг","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод килограммов в миллиграммы"},{"label":"Условная масса зерна, не универсальная для всех сортов","value":25,"unit":"мг","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Допущение задачи"}],"summary":"70 000 000 ÷ 25 = 2,8 млн зёрен."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-water-car', 'Сколько литровых бутылок воды весят как автомобиль массой 1,5 тонны? Считай, что литр воды весит 1 кг, а сами бутылки ничего не весят.', 'Сколько бутылок воды весят как автомобиль?', 'бутылок', 1500, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-12', '{"steps":[{"label":"Масса автомобиля по условию","value":1500,"unit":"кг","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — tonne = 1000 kg"},{"label":"Масса воды в одной бутылке принята условием","value":1,"unit":"кг","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Допущение задачи"}],"summary":"1,5 × 1000 ÷ 1 = 1500 бутылок."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-astana-almaty-steps', 'Представь прямую дорожку между Астаной и Алматы длиной 970 км. Сколько шагов по 70 см потребуется, чтобы её пройти? Расстояние 970 км используй как условие этой прикидки.', 'Сколько шагов от Астаны до Алматы по прямой?', 'шагов', 1385714, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-13', '{"steps":[{"label":"Длина условной дорожки задана вопросом","value":970000,"unit":"м","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод километров в метры; расстояние — допущение"},{"label":"Длина шага задана вопросом","value":0.7,"unit":"м","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод сантиметров в метры"}],"summary":"970 000 ÷ 0,7 ≈ 1,386 млн шагов. Это модель прямой дорожки, а не реального пешего маршрута."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-paper-tower', 'Сколько листов бумаги толщиной 0,1 мм нужно сложить в стопку высотой 828 м — как Бурдж-Халифа? Сжатие бумаги игнорируй.', 'Сколько листов в стопке высотой с Бурдж-Халифу?', 'листов', 8280000, 'https://www.burjkhalifa.ae/the-tower/', '2026-11-05', '2026-11-14', '{"steps":[{"label":"Высота башни, заданная условием","value":828,"unit":"м","sourceUrl":"https://www.burjkhalifa.ae/the-tower/","sourceTitle":"Burj Khalifa — официальный сайт башни"},{"label":"Толщина листа по условию","value":0.0001,"unit":"м","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод миллиметров в метры"}],"summary":"828 ÷ 0,0001 = 8 280 000 листов."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-basketballs-container', 'Сколько баскетбольных мячей диаметром 24 см войдёт в контейнер объёмом 33 м³, если сами мячи занимают 64% объёма? Все параметры этой модели заданы в вопросе.', 'Сколько баскетбольных мячей войдёт в контейнер?', 'мячей', 2918, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-15', '{"steps":[{"label":"Объём контейнера задан условием","value":33,"unit":"м³","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Допущение задачи"},{"label":"Доля объёма, занятая мячами, задана условием","value":0.64,"unit":"","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Допущение задачи"},{"label":"Радиус мяча из диаметра в условии","value":0.12,"unit":"м","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод сантиметров в метры"}],"summary":"33 × 0,64 ÷ (4π/3 × 0,12³) ≈ 2918 мячей. Краевые эффекты игнорируем."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-million-clips', 'Сколько суток уйдёт на просмотр миллиона роликов по 30 секунд, если смотреть круглосуточно без пауз?', 'Сколько суток смотреть миллион коротких роликов?', 'суток', 347.2222222222, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-16', '{"steps":[{"label":"Общая длительность по условию","value":30000000,"unit":"с","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Расчёт — миллион роликов по 30 секунд"},{"label":"Продолжительность суток","value":86400,"unit":"с","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — day = 86 400 s"}],"summary":"1 000 000 × 30 ÷ 86 400 ≈ 347,22 суток."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-coins-car', 'Сколько монет по 100 тенге нужно, чтобы их общая масса составила 1,5 тонны? Для этой задачи считай массу одной монеты равной 6,45 г.', 'Сколько монет по 100 тенге весят как автомобиль?', 'монет', 232558, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-17', '{"steps":[{"label":"Общая масса задана условием","value":1500000,"unit":"г","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — перевод тонн в граммы"},{"label":"Масса монеты принята условием задачи","value":6.45,"unit":"г","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Допущение задачи, не описание всех выпусков монеты"}],"summary":"1 500 000 ÷ 6,45 ≈ 232 558 монет."}', 1793894300896);
INSERT INTO tiebreaker_questions (id, prompt, card_prompt, unit, answer, source_url, as_of_date, active_date, explanation_json, created_at) VALUES ('tb-v4-sugar-bath', 'Сколько кубиков сахара с ребром 1,5 см поместится по суммарному объёму в ванне на 150 л? Игнорируй промежутки между кубиками и растворение сахара.', 'Сколько кубиков сахара заполнит ванну?', 'кубиков', 44444, 'https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8', '2026-11-05', '2026-11-18', '{"steps":[{"label":"Объём ванны задан условием","value":150000,"unit":"см³","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"NIST — 1 л = 1000 см³"},{"label":"Объём кубика по размерам из условия","value":3.375,"unit":"см³","sourceUrl":"https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8","sourceTitle":"Расчёт — 1,5 × 1,5 × 1,5"}],"summary":"150 000 ÷ 3,375 ≈ 44 444 кубика по объёму."}', 1793894300896);
